import{_ as r,K as d,a as l,c as a,ac as e,q as i}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"Codex 模型对比与选择","description":"GPT-5.6 系列的历史模型分工与 Go 任务路由记录","frontmatter":{"title":"Codex 模型对比与选择","description":"GPT-5.6 系列的历史模型分工与 Go 任务路由记录","sources":[{"repository":"TeamDocs","file":"docs/engineering/codex/Model-Selection.md"}],"showdocs":{"topics":[{"id":"ai","title":"AI 与 Codex","link":"/topics/ai/"}],"kind":"AI与Codex任务与配置","scope":"historical","audience":"general","group":"工程与工具","summary":"GPT-5.6 系列的历史模型分工与 Go 任务路由记录","status":"active","related":[{"title":"AI与Codex：完整实践与解答","link":"/tools/ai/practice/application","kind":"AI与Codex完整实践与解答","scope":"general","audience":"general"},{"title":"Codex Token 计算规则","link":"/tools/ai/reference/token-calculation","kind":"AI与Codex任务与配置","scope":"historical","audience":"general"},{"title":"全局 AGENTS.md","link":"/tools/ai/guide/global-agents","kind":"AI与Codex上手与对象","scope":"general","audience":"general"},{"title":"AI辅助开发的任务、上下文与验收","link":"/tools/ai/assisted-development-workflow","kind":"AI与Codex上手与对象","scope":"general","audience":"general"},{"title":"Codex 插件用途与选择记录","link":"/tools/ai/reference/plugin","kind":"AI与Codex任务与配置","scope":"historical","audience":"general"}],"prev":{"text":"Codex 插件用途与选择记录","link":"/tools/ai/reference/plugin"},"next":{"text":"Codex Token 计算规则","link":"/tools/ai/reference/token-calculation"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Codex 插件用途与选择记录","link":"/tools/ai/reference/plugin"},"next":{"text":"Codex Token 计算规则","link":"/tools/ai/reference/token-calculation"}},"headers":[],"relativePath":"tools/ai/reference/model-selection.md","filePath":"tools/ai/reference/model-selection.md"}'),n={name:"tools/ai/reference/model-selection.md"};function s(g,t,h,p,u,c){const o=d("Mermaid");return l(),a("div",null,[t[0]||(t[0]=e('<h1 id="codex-模型对比与选择" tabindex="-1">Codex 模型对比与选择 <a class="header-anchor" href="#codex-模型对比与选择" aria-label="Permalink to &quot;Codex 模型对比与选择&quot;">​</a></h1><blockquote><p>历史范围：本文保留来源记录中的模型系列、费率示例和界面名称，未将其核验为当前可用配置。计量方法与任务组织原则可参考；实际模型和价格请以文末官方入口及账号界面为准。</p></blockquote><p>Codex 是 ChatGPT 中用于读取、修改、运行、测试和审查代码的智能代理。ChatGPT Plus、Pro 是订阅方案，模型则是 Codex 执行任务时使用的能力引擎。订阅档位主要影响可用额度，不等于模型名称。</p><p>模型、额度和可用范围可能随官方发布及账号灰度而变化；实际使用时请以 Codex 模型选择器和 OpenAI 官方页面为准。</p><h2 id="一、快速结论" tabindex="-1">一、快速结论 <a class="header-anchor" href="#一、快速结论" aria-label="Permalink to &quot;一、快速结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>定位</th><th>能力</th><th>速度</th><th>相对消耗</th><th>推荐场景</th></tr></thead><tbody><tr><td><strong>GPT-5.6 Sol</strong></td><td>旗舰模型</td><td>最高</td><td>中等</td><td>最高</td><td>架构设计、复杂 Bug、大型重构、高风险任务</td></tr><tr><td><strong>GPT-5.6 Terra</strong></td><td>平衡型主力</td><td>很高</td><td>快</td><td>中等</td><td>日常功能开发、常规重构、测试与 Review</td></tr><tr><td><strong>GPT-5.6 Luna</strong></td><td>高吞吐模型</td><td>中高</td><td>很快</td><td>较低</td><td>批量修改、抽取、分类、格式转换</td></tr><tr><td><strong>GPT-5.3-Codex-Spark</strong></td><td>低延迟模型</td><td>中等</td><td>极快</td><td>独立限额</td><td>小范围、交互式代码修改（Pro 研究预览）</td></tr><tr><td><strong>GPT-5.4 Mini</strong></td><td>轻量模型</td><td>中等</td><td>快</td><td>最低</td><td>扫描、整理和低风险子任务</td></tr></tbody></table><p>最实用的选择规则：</p><ul><li>不知道选什么：<strong>Sol + Medium</strong>。</li><li>日常 Go 服务开发：<strong>Terra + Medium</strong>。</li><li>复杂架构、并发问题或线上疑难问题：<strong>Sol + High</strong>。</li><li>明确、重复、可批量验证的任务：<strong>Luna + Low / Medium</strong>。</li><li>只改几行代码并追求即时反馈：可用 <strong>Spark</strong>（账号可用时）。</li></ul><h2 id="二、核心模型怎么选" tabindex="-1">二、核心模型怎么选 <a class="header-anchor" href="#二、核心模型怎么选" aria-label="Permalink to &quot;二、核心模型怎么选&quot;">​</a></h2><h3 id="gpt-5-6-sol-复杂任务和最终把关" tabindex="-1">GPT-5.6 Sol：复杂任务和最终把关 <a class="header-anchor" href="#gpt-5-6-sol-复杂任务和最终把关" aria-label="Permalink to &quot;GPT-5.6 Sol：复杂任务和最终把关&quot;">​</a></h3><p>Sol 适合需求模糊、影响范围大、错误成本高的任务。它通常更善于主动寻找隐藏依赖、分析边界条件，并完成从代码探索到验证的长链路工作。</p><p>典型场景：</p><ul><li>跨模块、跨服务或跨仓库修改</li><li>微服务架构设计与大型重构</li><li>Goroutine 泄漏、死锁、竞态和锁竞争</li><li>GC 抖动、内存增长和 pprof 分析</li><li>数据迁移、协议升级与兼容性设计</li><li>生产事故根因分析、安全审查</li><li>对其他模型或子任务产出做最终验收</li></ul><p>Sol 的成本和推理耗时最高。简单 CRUD、字段修改或格式转换没有必要默认使用它。</p><h3 id="gpt-5-6-terra-日常开发主力" tabindex="-1">GPT-5.6 Terra：日常开发主力 <a class="header-anchor" href="#gpt-5-6-terra-日常开发主力" aria-label="Permalink to &quot;GPT-5.6 Terra：日常开发主力&quot;">​</a></h3><p>Terra 在能力、速度和额度之间最均衡，适合团队大多数日常研发任务。它比 Luna 更能应对不完全明确的需求，又比 Sol 更适合高频使用。</p><p>典型场景：</p><ul><li>API、CRUD 和后台功能开发</li><li>MySQL、Redis、RPC 等常规业务逻辑</li><li>修复范围明确的 Bug</li><li>编写单元测试、配置和 SQL</li><li>中小型重构、日志与错误码完善</li><li>常规代码审查、lint、test 和 build</li><li>阅读代码、补充开发文档</li></ul><p>建议将 <strong>Terra + Medium</strong> 作为日常默认配置，遇到复杂或高风险任务再切换 Sol。</p><h3 id="gpt-5-6-luna-明确任务的高性价比选择" tabindex="-1">GPT-5.6 Luna：明确任务的高性价比选择 <a class="header-anchor" href="#gpt-5-6-luna-明确任务的高性价比选择" aria-label="Permalink to &quot;GPT-5.6 Luna：明确任务的高性价比选择&quot;">​</a></h3><p>Luna 适合验收标准清楚、格式固定、可以批量执行的任务。它速度快、消耗低，但对模糊需求、架构取舍和隐藏副作用的判断弱于 Sol 和 Terra。</p><p>典型场景：</p><ul><li>批量补充简单单元测试</li><li>批量改名、补注释或统一日志格式</li><li>JSON、YAML、TOML 和 SQL 结构转换</li><li>从代码中抽取接口、配置或错误码清单</li><li>日志分类、文档整理和结构化总结</li><li>按固定模板生成低风险代码</li></ul><p>使用 Luna 时应把文件范围、转换规则、禁止修改项和验收命令写清楚。高风险批量修改完成后，建议再由 Terra 或 Sol 审查。</p><h3 id="旧模型与特殊模型" tabindex="-1">旧模型与特殊模型 <a class="header-anchor" href="#旧模型与特殊模型" aria-label="Permalink to &quot;旧模型与特殊模型&quot;">​</a></h3><ul><li><strong>GPT-5.5 / GPT-5.4</strong>：主要用于兼容旧工作流或复现历史结果；新任务通常优先使用 5.6 系列。</li><li><strong>GPT-5.4 Mini</strong>：适合极低成本的简单扫描和机械修改；通常优先考虑能力更强的 Luna。</li><li><strong>GPT-5.3-Codex-Spark</strong>：强调近实时交互，适合快速、小范围修改，目前主要面向 Pro 研究预览。</li><li><strong>GPT-5.3-Codex / GPT-5.2</strong>：不建议在新的 ChatGPT 登录工作流中继续配置。</li><li><strong>GPT-5.5 Cyber</strong>：特殊安全访问模型，不属于普通 Plus/Pro 的常规模型。</li></ul><h2 id="三、推理等级怎么选" tabindex="-1">三、推理等级怎么选 <a class="header-anchor" href="#三、推理等级怎么选" aria-label="Permalink to &quot;三、推理等级怎么选&quot;">​</a></h2><p>模型决定能力上限，推理等级决定单次任务投入多少分析与执行资源。</p><table tabindex="0"><thead><tr><th>等级</th><th>适用任务</th><th>使用建议</th></tr></thead><tbody><tr><td><strong>Low</strong></td><td>字段修改、格式转换、简单测试、明确编译错误</td><td>范围小、结果可快速验证</td></tr><tr><td><strong>Medium</strong></td><td>常规功能、多文件修改、API 与数据库接入</td><td>日常默认</td></tr><tr><td><strong>High</strong></td><td>复杂 Bug、状态机、性能问题、大型模块分析</td><td>需要主动验证多个假设</td></tr><tr><td><strong>Extra High</strong></td><td>高风险迁移、跨服务改造、安全相关代码</td><td>错误成本较高时使用</td></tr><tr><td><strong>Max</strong></td><td>极难复现问题、复杂架构、单代理深度分析</td><td>不建议作为默认配置</td></tr><tr><td><strong>Ultra</strong></td><td>可拆分的大型探索、迁移或审计任务</td><td>多代理并行，消耗最高</td></tr></tbody></table><p>不要仅通过提高推理等级来弥补不清楚的需求。明确入口文件、修改范围、业务约束和验收方式，往往比盲目使用 Max 更有效。</p><h2 id="四、go-服务端任务选择表" tabindex="-1">四、Go 服务端任务选择表 <a class="header-anchor" href="#四、go-服务端任务选择表" aria-label="Permalink to &quot;四、Go 服务端任务选择表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>推荐组合</th><th>原因</th></tr></thead><tbody><tr><td>单个接口、CRUD、分页查询</td><td>Terra + Medium</td><td>多文件开发的能力与成本平衡最好</td></tr><tr><td>增加字段、修改 Tag 或配置</td><td>Luna + Low</td><td>规则明确、容易验证</td></tr><tr><td>普通 Bug 修复</td><td>Terra + Medium / High</td><td>能兼顾定位、修改和测试</td></tr><tr><td>并发、死锁、泄漏、竞态</td><td>Sol + High</td><td>需要分析完整生命周期和隐藏路径</td></tr><tr><td>难以复现的线上问题</td><td>Sol + Max</td><td>需要更深入的假设验证</td></tr><tr><td>微服务拆分、协议或数据迁移</td><td>Sol + Extra High</td><td>影响范围大、兼容风险高</td></tr><tr><td>大型且可并行的跨仓库改造</td><td>Sol + Ultra</td><td>可并行探索、实现与验证</td></tr><tr><td>批量补测试或机械修改</td><td>Luna + Medium</td><td>高吞吐、低消耗</td></tr><tr><td>常规代码 Review</td><td>Terra + High</td><td>质量与成本平衡</td></tr><tr><td>发布前高风险 Review</td><td>Sol + High</td><td>更适合最终风险把关</td></tr><tr><td>pprof、GC、锁竞争、慢查询</td><td>Sol + High</td><td>需要综合代码、指标和运行数据</td></tr></tbody></table><h2 id="五、推荐的三级路由" tabindex="-1">五、推荐的三级路由 <a class="header-anchor" href="#五、推荐的三级路由" aria-label="Permalink to &quot;五、推荐的三级路由&quot;">​</a></h2><p>团队可以按任务风险和清晰度路由，而不是始终使用最强模型：</p>',34)),i(o,{source:""}),t[1]||(t[1]=e('<p>推荐实践：</p><ol><li><strong>Terra 处理大多数日常开发</strong>，保持速度和额度平衡。</li><li><strong>Luna 承担明确的批量工作</strong>，但必须给出严格范围和验收命令。</li><li><strong>Sol 负责难题、方案决策和最终把关</strong>，避免在高风险任务上因反复返工而增加总成本。</li></ol><h2 id="六、影响消耗的不只是模型" tabindex="-1">六、影响消耗的不只是模型 <a class="header-anchor" href="#六、影响消耗的不只是模型" aria-label="Permalink to &quot;六、影响消耗的不只是模型&quot;">​</a></h2><p>实际额度消耗还受代码库大小、上下文长度、推理等级、输出长度和工具调用次数影响。大型仓库中，以下做法通常比单纯切换廉价模型更有效：</p><ul><li>缩小工作目录和任务范围。</li><li>提供入口文件、相关模块和历史实现位置。</li><li>明确禁止扫描或修改的目录。</li><li>使用 <code>AGENTS.md</code> 固化工程规则和验证命令。</li><li>要求先检查 <code>git diff</code>，避免重复读取无关文件。</li><li>排除 vendor、生成文件、大日志和构建产物。</li><li>将复杂任务拆成边界清晰、可分别验收的阶段。</li></ul><h2 id="七、参考资料" tabindex="-1">七、参考资料 <a class="header-anchor" href="#七、参考资料" aria-label="Permalink to &quot;七、参考资料&quot;">​</a></h2><ul><li><a href="https://developers.openai.com/codex/models" target="_blank" rel="noopener noreferrer">Codex 模型</a></li><li><a href="https://developers.openai.com/codex/pricing" target="_blank" rel="noopener noreferrer">Codex 定价</a></li><li><a href="https://help.openai.com/en/articles/6950777-what-is-chatgpt-plus" target="_blank" rel="noopener noreferrer">ChatGPT Plus 说明</a></li><li><a href="https://help.openai.com/en/articles/9793128-about-chatgpt-pro" target="_blank" rel="noopener noreferrer">ChatGPT Pro 说明</a></li></ul>',7))])}const T=r(n,[["render",s]]);export{m as __pageData,T as default};
